package com.printflow.customer;
import com.printflow.identity.*;import com.printflow.files.ArtifactStorage;import java.util.*;import java.time.*;import java.io.IOException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
/** Minimal manually confirmed operations. Task completion alone never changes public work progress. */
@RestController public class FulfilmentController {
 public record Action(@Min(0) long revision,@NotBlank @Pattern(regexp="PRODUCTION|READY|IN_TRANSIT|DELIVERED|ISSUE|RESOLVE") String action,@NotBlank @Size(min=10,max=500) String note,@AssertTrue boolean confirmed){}
 private final JdbcTemplate db;private final ProjectNotifications mail;private final ArtifactStorage store;private final Payments payments;private final ProductionQueue queue;private final DeliveryPhotos photos;
 public FulfilmentController(JdbcTemplate db,ProjectNotifications mail,ArtifactStorage store,Payments payments,ProductionQueue queue,DeliveryPhotos photos){this.queue=queue;this.photos=photos;this.db=db;this.mail=mail;this.store=store;this.payments=payments;}
 private ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}
 private Map<String,Object> scope(StaffPrincipal u,UUID id,boolean lock){var rows=db.queryForList("select id,status,customer_user_id,assigned_staff_id,designer_id from enquiries where id=?"+(lock?" for update":""),id);if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();boolean allowed=switch(u.role()){case "OWNER"->true;case "CUSTOMER"->u.id().equals(e.get("customer_user_id"));case "DESIGNER"->u.id().equals(e.get("designer_id"));case "SALES"->u.id().equals(e.get("assigned_staff_id"));case "OPERATOR","DELIVERY"->db.queryForObject("select exists(select 1 from staff_job_tasks where enquiry_id=? and staff_id=? and job_role=?) or exists(select 1 from production_jobs where enquiry_id=? and operator_id=? and ?='OPERATOR')",Boolean.class,id,u.id(),u.role(),id,u.id(),u.role());default->false;};if(!allowed)throw new NoSuchElementException();return e;}
 private Map<String,Object> current(UUID id){var rows=db.queryForList("select state,revision,proof_id,quote_id,delivered_at,issue_open,photos_required from fulfilment_work where enquiry_id=?",id);return rows.isEmpty()?new LinkedHashMap<>(Map.of("state","NOT_STARTED","revision",0,"issue_open",false)):rows.getFirst();}
 @GetMapping("/api/v1/design/enquiries/{id}/fulfilment") public ResponseEntity<?> view(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id){var e=scope(u,id,false);var result=new LinkedHashMap<>(current(id));var jobs=db.queryForList("select stage,hold_reason from production_jobs where enquiry_id=?",id);if(!jobs.isEmpty()){result.put("productionStage",jobs.getFirst().get("stage"));result.put("productionHold",jobs.getFirst().get("hold_reason"));}result.put("evidenceReadiness",Map.of("pickup",photos.readiness(id,"PICKUP"),"delivery",photos.readiness(id,"DELIVERY")));result.put("owner",u.role().equals("OWNER"));result.put("printer",u.role().equals("OPERATOR"));result.put("delivery",u.role().equals("DELIVERY"));result.put("closed","CLOSED".equals(e.get("status")));return response(result);}
 @PostMapping("/api/v1/design/enquiries/{id}/fulfilment") @Transactional(rollbackFor=Exception.class) public ResponseEntity<?> act(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Action input)throws IOException{
  if(input.note().trim().length()<10)throw new IllegalArgumentException("Provide a meaningful customer-visible progress note");
  var e=scope(u,id,true);if("CLOSED".equals(e.get("status")))throw conflict("Closed work is read-only");var work=current(id);long revision=((Number)work.get("revision")).longValue();if(revision!=input.revision())throw conflict("Work changed; refresh first");String old=work.get("state").toString(),next=input.action();boolean owner=u.role().equals("OWNER");
  if(next.equals("ISSUE")){if(!Set.of("CUSTOMER","OWNER").contains(u.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!old.equals("DELIVERED")||Boolean.TRUE.equals(work.get("issue_open")))throw conflict("Report an issue during delivered review");db.update("update fulfilment_work set issue_open=true,revision=revision+1,updated_at=now() where enquiry_id=?",id);event(id,u.id(),"DELIVERY_ISSUE",input.note());return view(u,id);}
  if(next.equals("RESOLVE")){if(!owner)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!old.equals("DELIVERED")||!Boolean.TRUE.equals(work.get("issue_open")))throw conflict("No delivery issue to resolve");db.update("update fulfilment_work set issue_open=false,delivered_at=now(),revision=revision+1,updated_at=now() where enquiry_id=?",id);event(id,u.id(),"ISSUE_FIXED",input.note()+". The 48-hour review window restarted.");return view(u,id);}
  boolean permission=owner||next.equals("READY")&&u.role().equals("OPERATOR")||Set.of("IN_TRANSIT","DELIVERED").contains(next)&&u.role().equals("DELIVERY");if(!permission)throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  String expected=switch(next){case "PRODUCTION"->"NOT_STARTED";case "READY"->"PRODUCTION";case "IN_TRANSIT"->"READY";case "DELIVERED"->"IN_TRANSIT";default->"INVALID";};if(!old.equals(expected))throw conflict("Complete the current stage before advancing");
  var proof=approved(id);if(next.equals("PRODUCTION")){if(db.queryForObject("select exists(select 1 from quote_versions where enquiry_id=? and state='ISSUED')",Boolean.class,id))throw conflict("Resolve the outstanding quotation or amendment before production release");if(!"IN_PROGRESS".equals(e.get("status")))throw conflict("An accepted live order is required");payments.require(id,(UUID)proof.get("quote_id"),false);try(var verified=store.verified((UUID)proof.get("artifact_id"),((Number)proof.get("byte_size")).longValue(),proof.get("sha256").toString())){}db.update("insert into fulfilment_work(enquiry_id,state,proof_id,quote_id,released_by) values(?,'PRODUCTION',?,?,?)",id,proof.get("id"),proof.get("quote_id"),u.id());db.update("update fulfilment_work set photos_required=true where enquiry_id=?",id);queue.released(id);}
  else{if(next.equals("READY"))queue.qualityRequired(id);if(next.equals("IN_TRANSIT")){payments.require(id,(UUID)proof.get("quote_id"),true);photos.require(id,"PICKUP");}if(next.equals("DELIVERED"))photos.require(id,"DELIVERY");if(!proof.get("id").equals(work.get("proof_id"))||!proof.get("quote_id").equals(work.get("quote_id")))throw conflict("Production agreement or proof changed; contact owner");db.update("update fulfilment_work set state=?,revision=revision+1,delivered_at=case when ?='DELIVERED' then now() else delivered_at end,updated_at=now() where enquiry_id=?",next,next,id);}
  if(next.equals("READY"))queue.ready(id);
  String text=switch(next){case "PRODUCTION"->"Production has been released to the queue after owner approval of the exact proof.";case "READY"->"Production and quality checks are confirmed complete. Work is ready for dispatch.";case "IN_TRANSIT"->"Your work has been dispatched and is in transit.";default->"Delivery has been confirmed. Your 48-hour review period has started; report an issue in Live works if needed.";};event(id,u.id(),next,text+" "+input.note());return view(u,id);
 }
 private Map<String,Object> approved(UUID id){var rows=db.queryForList("select p.id,p.artifact_id,p.quote_id,a.byte_size,a.sha256,a.state,d.action,q.state as agreement from proof_revisions p join design_artifacts a on a.id=p.artifact_id join quote_versions q on q.id=p.quote_id left join proof_decisions d on d.proof_id=p.id where p.enquiry_id=? order by p.revision desc limit 1",id);if(rows.isEmpty())throw conflict("The current proof must be approved first");var p=rows.getFirst();if(!"CLEAN".equals(p.get("state"))||!"APPROVE".equals(p.get("action"))||!"ACCEPTED".equals(p.get("agreement")))throw conflict("The current clean proof and quotation must be approved");return p;}
 private void event(UUID id,UUID actor,String kind,String text){UUID event=UUID.randomUUID();db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,?,?)",event,id,actor,kind,text);mail.both(id,kind.equals("DELIVERY_ISSUE")?"ISSUE":kind.equals("PRODUCTION")?"PRODUCTION":kind.equals("IN_TRANSIT")?"TRANSIT":kind.equals("ISSUE_FIXED")?"ISSUE_FIXED":kind,event,text);}
 @Scheduled(fixedDelay=60000) @Transactional public void completeDue(){var ids=db.queryForList("select e.id from enquiries e join fulfilment_work f on f.enquiry_id=e.id where e.status='IN_PROGRESS' and f.state='DELIVERED' and not f.issue_open and f.delivered_at<=now()-interval '48 hours' order by e.id limit 100 for update of e skip locked");for(var row:ids){UUID id=(UUID)row.get("id");if(db.update("update fulfilment_work set state='COMPLETED',revision=revision+1,updated_at=now() where enquiry_id=? and state='DELIVERED' and not issue_open and delivered_at<=now()-interval '48 hours'",id)!=1)continue;db.update("update enquiries set status='CLOSED',closure_kind='COMPLETED',closure_message='Delivered and completed after the 48-hour review window.',revision=revision+1,updated_at=now() where id=?",id);db.update("insert into enquiry_events(id,enquiry_id,event_type,from_status,to_status) values(?,?,'AUTO_COMPLETE','IN_PROGRESS','CLOSED')",UUID.randomUUID(),id);event(id,null,"COMPLETED","Work completed automatically after 48 hours with no open delivery issue.");}}
 private ResponseEntity<?> response(Object body){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(body);}
}
